{
  "candidate_lineage_id": "2026-10-26-rdmv-ut-class-d:lineage:90",
  "input_manifest_sha256": "433aa467767a6356328ade20155dc6bab2b57d94737965d6a21238aae9e89cec",
  "schema_version": "teaching-unit.v0.4.0",
  "source_registry_sha256": "ea788fb291dc481354040e727c748644403770f10da117ffd0981061e85c488e",
  "units": [
    {
      "memory_support": {
        "fact_ids": [
          "sec07-R01",
          "sec07-R02",
          "sec07-R03"
        ],
        "text": "Back on seat, ten inches gap, wheel low, headrest above ears."
      },
      "misconception": {
        "claim": {
          "fact_ids": [
            "sec07-F02"
          ],
          "text": "Common mistake, many people think crowding close to the wheel improves control, which is wrong."
        },
        "correction": {
          "fact_ids": [
            "sec07-F02",
            "sec07-R01"
          ],
          "text": "Stay upright with back supported and keep about ten inches between chest and wheel for control and distance."
        }
      },
      "module_id": "sec07-m01",
      "objective_ids": [
        "sec07-F01",
        "sec07-F02",
        "sec07-R01"
      ],
      "self_check": {
        "answer": {
          "fact_ids": [
            "sec07-F02"
          ],
          "text": "About ten inches of space, seatback upright, wheel top at or below shoulder and chin height."
        },
        "prompt": {
          "fact_ids": [
            "sec07-F02"
          ],
          "text": "You settle into the driver seat before starting. What spacing and wheel height do you set?"
        },
        "rationale": {
          "fact_ids": [
            "sec07-F02"
          ],
          "text": "That spacing preserves steering control while keeping distance from a deploying air bag."
        }
      },
      "slides": [
        {
          "estimated_narration_seconds": 45,
          "kind": "opening",
          "lines": [
            {
              "fact_ids": [
                "sec07-F01"
              ],
              "text": "Sit upright with steady support."
            },
            {
              "fact_ids": [
                "sec07-F01"
              ],
              "text": "Feet rest ready for smooth pedals."
            }
          ],
          "media_absence_reason": "text_first_pilot",
          "media_role": "none",
          "narration": {
            "fact_ids": [
              "sec07-F01"
            ],
            "text": "Getting seated well changes everything that follows in this drive. You sit upright with your back supported, feet resting on the floor, and pedals comfortably reachable. That base posture steadies your steering, your mirror view, and your pedal touch. Without it, every later adjustment feels off. So we start here, building a calm and ready driving position that supports safe control from the first moment behind the wheel."
          },
          "slide_id": "sec07-u01-s01",
          "title": {
            "fact_ids": [
              "sec07-F01"
            ],
            "text": "Start With Solid Posture"
          }
        },
        {
          "estimated_narration_seconds": 48,
          "kind": "concept",
          "lines": [
            {
              "fact_ids": [
                "sec07-F01"
              ],
              "text": "Back supported against the seat."
            },
            {
              "fact_ids": [
                "sec07-F01"
              ],
              "text": "Feet on floor, pedals reachable."
            },
            {
              "fact_ids": [
                "sec07-F03"
              ],
              "text": "Heel stays grounded between pedals."
            }
          ],
          "media_absence_reason": "text_first_pilot",
          "media_role": "none",
          "narration": {
            "fact_ids": [
              "sec07-F01",
              "sec07-F03"
            ],
            "text": "Your seat is the foundation for control. Sit upright with your back against the seat and feet on the floor, so pedals stay comfortably reachable. You move your foot between pedals with the heel staying on the floor, which keeps motion smooth and prevents slips. This grounded posture reduces fatigue and helps you respond quickly. Once your lower body feels stable, your hands and eyes can work with far less effort and more confidence on every trip."
          },
          "slide_id": "sec07-u01-s02",
          "title": {
            "fact_ids": [
              "sec07-F01"
            ],
            "text": "Upright Seat, Ready Feet"
          }
        },
        {
          "estimated_narration_seconds": 48,
          "kind": "concept",
          "lines": [
            {
              "fact_ids": [
                "sec07-F02"
              ],
              "text": "Keep ten inches from chest."
            },
            {
              "fact_ids": [
                "sec07-F02"
              ],
              "text": "Seatback stays upright, not reclined."
            },
            {
              "fact_ids": [
                "sec07-R02"
              ],
              "text": "Wheel top low below chin."
            }
          ],
          "media_absence_reason": "text_first_pilot",
          "media_role": "none",
          "narration": {
            "fact_ids": [
              "sec07-F02",
              "sec07-R02"
            ],
            "text": "Distance from the wheel protects both control and safety. Keep about ten inches of space between chest and steering wheel, with the seatback upright. Keep the top of the wheel at shoulder height or lower and below chin level. That arrangement gives your arms room to steer smoothly while keeping space from a deploying air bag. Reclining or crowding forward weakens leverage, so hold this measured gap each time you drive."
          },
          "slide_id": "sec07-u01-s03",
          "title": {
            "fact_ids": [
              "sec07-F02"
            ],
            "text": "Ten Inches Protects Control"
          }
        },
        {
          "estimated_narration_seconds": 45,
          "kind": "concept",
          "lines": [
            {
              "fact_ids": [
                "sec07-F03"
              ],
              "text": "Headrest touches above ear level."
            },
            {
              "fact_ids": [
                "sec07-F03"
              ],
              "text": "Supports head, reduces whiplash risk."
            },
            {
              "fact_ids": [
                "sec07-R03"
              ],
              "text": "Adjust before you start driving."
            }
          ],
          "media_absence_reason": "text_first_pilot",
          "media_role": "none",
          "narration": {
            "fact_ids": [
              "sec07-F03",
              "sec07-R03"
            ],
            "text": "The headrest is a safety device, not a comfort pillow. Position the headrest to touch the back of the head above ear level. That contact helps limit rearward head motion and reduces whiplash risk. Many drivers leave it too low or with a gap, which removes the benefit. Take a moment to raise or align it before moving. A small adjustment now adds meaningful protection if your vehicle is struck from behind."
          },
          "slide_id": "sec07-u01-s04",
          "title": {
            "fact_ids": [
              "sec07-F03"
            ],
            "text": "Raise Headrest Above Ears"
          }
        },
        {
          "estimated_narration_seconds": 46,
          "kind": "trap",
          "lines": [
            {
              "fact_ids": [
                "sec07-F01",
                "sec07-F02"
              ],
              "text": "Posture or distance: which adjustment first?"
            },
            {
              "fact_ids": [
                "sec07-F01",
                "sec07-F02"
              ],
              "text": "Upright reach differs from ten-inch gap."
            }
          ],
          "media_absence_reason": "text_first_pilot",
          "media_role": "none",
          "narration": {
            "fact_ids": [
              "sec07-F01",
              "sec07-F02"
            ],
            "text": "These two seat rules are easy to mix, so sort them carefully. Sitting upright with pedals reachable describes your base posture, while about ten inches between chest and wheel describes your air-bag distance and steering leverage. Both govern seat fit, but they test different measurements. Set posture first, then slide the seat to earn the gap, then set wheel height low. Keeping the pair distinct prevents the crowded or reclined errors that reduce control."
          },
          "slide_id": "sec07-u01-s05",
          "title": {
            "fact_ids": [
              "sec07-F01",
              "sec07-F02"
            ],
            "text": "Do Not Mix Fit Rules"
          }
        },
        {
          "estimated_narration_seconds": 44,
          "kind": "self_check",
          "lines": [
            {
              "fact_ids": [
                "sec07-F02"
              ],
              "text": "What spacing keeps steering and safety?"
            },
            {
              "fact_ids": [
                "sec07-F02"
              ],
              "text": "Recall upright back and low wheel."
            }
          ],
          "media_absence_reason": "text_first_pilot",
          "media_role": "none",
          "narration": {
            "fact_ids": [
              "sec07-F02"
            ],
            "text": "Here is a quick check: picture yourself settling into the driver seat before starting. What spacing and wheel height do you set for safe control. You keep about ten inches between chest and wheel, seatback upright, with the wheel top at or below shoulder and chin height. That answer shows you hold both distance and leverage together. Carry that image into every vehicle you drive and confirm it before moving."
          },
          "slide_id": "sec07-u01-s06",
          "title": {
            "fact_ids": [
              "sec07-F02"
            ],
            "text": "Check Your Seat Setup"
          }
        },
        {
          "estimated_narration_seconds": 42,
          "kind": "close",
          "lines": [
            {
              "fact_ids": [
                "sec07-R01"
              ],
              "text": "Upright, ten inches, wheel low."
            },
            {
              "fact_ids": [
                "sec07-R03"
              ],
              "text": "Headrest high, heel grounded always."
            }
          ],
          "media_absence_reason": "text_first_pilot",
          "media_role": "none",
          "narration": {
            "fact_ids": [
              "sec07-R01",
              "sec07-R03"
            ],
            "text": "You now have a repeatable seat routine. Sit upright with your back on the seat, keep ten inches to the wheel, keep the wheel top low, position the headrest above ear level, and keep your heel grounded. Run this short checklist before mirrors and belts. Consistent setup builds smooth steering, clear vision, and better protection. Make it automatic, and every drive begins from a strong and safe foundation."
          },
          "slide_id": "sec07-u01-s07",
          "title": {
            "fact_ids": [
              "sec07-R01"
            ],
            "text": "Lock In Seat Routine"
          }
        }
      ],
      "title": {
        "fact_ids": [
          "sec07-F01"
        ],
        "text": "Sit Right Before Driving"
      },
      "unit_id": "sec07-u01",
      "why_how": [
        {
          "fact_ids": [
            "sec07-F01"
          ],
          "text": "Sitting upright with support and reachable pedals creates stable control before mirrors and belts are set."
        },
        {
          "fact_ids": [
            "sec07-F02"
          ],
          "text": "Ten inches of chest space with an upright seatback and low wheel preserves steering leverage and air-bag distance."
        },
        {
          "fact_ids": [
            "sec07-F03"
          ],
          "text": "Headrest contact above ear level plus heel on the floor reduces whiplash risk and prevents pedal error."
        }
      ],
      "worked_example": {
        "reasoning": {
          "fact_ids": [
            "sec07-F02"
          ],
          "text": "Sliding back earns the ten-inch gap without reclining, and lowering the wheel keeps it at or below shoulder height."
        },
        "result": {
          "fact_ids": [
            "sec07-F02"
          ],
          "text": "The driver gains smooth steering leverage and safe distance from the wheel."
        },
        "scenario": {
          "fact_ids": [
            "sec07-F01"
          ],
          "text": "A new driver sits crowded near the wheel with the seatback tilted and struggles to turn smoothly."
        }
      }
    },
    {
      "memory_support": {
        "fact_ids": [
          "sec07-F04",
          "sec07-F05"
        ],
        "text": "Frame rear window inside, sliver outside to shrink blind spots."
      },
      "misconception": {
        "claim": {
          "fact_ids": [
            "sec07-F05"
          ],
          "text": "Myth: outside mirrors should show much of your own car side, which is not true."
        },
        "correction": {
          "fact_ids": [
            "sec07-F05",
            "sec07-R04"
          ],
          "text": "Set outside mirrors so only a sliver of the vehicle side shows, widening neighboring-lane coverage from a normal seated position."
        }
      },
      "module_id": "sec07-m02",
      "objective_ids": [
        "sec07-F04",
        "sec07-F05"
      ],
      "self_check": {
        "answer": {
          "fact_ids": [
            "sec07-F05"
          ],
          "text": "Only a sliver of the vehicle side shows, giving wider coverage of neighboring lanes."
        },
        "prompt": {
          "fact_ids": [
            "sec07-F05"
          ],
          "text": "From your normal seated position, how much vehicle side belongs in the outside mirrors?"
        },
        "rationale": {
          "fact_ids": [
            "sec07-F05"
          ],
          "text": "A narrow sliver setting shrinks blind spots instead of wasting mirror space on your own car."
        }
      },
      "slides": [
        {
          "estimated_narration_seconds": 44,
          "kind": "opening",
          "lines": [
            {
              "fact_ids": [
                "sec07-F04"
              ],
              "text": "Clear mirrors reveal the road."
            },
            {
              "fact_ids": [
                "sec07-F05"
              ],
              "text": "Small settings prevent big surprises."
            }
          ],
          "media_absence_reason": "text_first_pilot",
          "media_role": "none",
          "narration": {
            "fact_ids": [
              "sec07-F04"
            ],
            "text": "Before you move, your mirrors decide what you will see. Correct mirrors give a steady rear view and wider lane coverage, while poor mirrors hide traffic beside you. This short session teaches inside framing and outside width in order. The steps take seconds at the curb and pay off on every lane change. Learn them once, repeat them always, and drive with far fewer blind surprises around your vehicle."
          },
          "slide_id": "sec07-u02-s01",
          "title": {
            "fact_ids": [
              "sec07-F04"
            ],
            "text": "See Clearly Before Moving"
          }
        },
        {
          "estimated_narration_seconds": 46,
          "kind": "concept",
          "lines": [
            {
              "fact_ids": [
                "sec07-F04"
              ],
              "text": "Center mirror on rear window."
            },
            {
              "fact_ids": [
                "sec07-F04"
              ],
              "text": "Match day or night setting."
            },
            {
              "fact_ids": [
                "sec07-F04"
              ],
              "text": "Reduces glare, steadies rear view."
            }
          ],
          "media_absence_reason": "text_first_pilot",
          "media_role": "none",
          "narration": {
            "fact_ids": [
              "sec07-F04"
            ],
            "text": "Your inside mirror has one clear job. Center the inside mirror on the rear window and select the day or night setting to match driving conditions. That centered framing keeps the view behind you stable, while the correct setting cuts nighttime glare from headlights. Check it from your normal seated position after the seat is set. A centered, glare-controlled mirror lets you judge following traffic quickly and calmly without leaning or guessing."
          },
          "slide_id": "sec07-u02-s02",
          "title": {
            "fact_ids": [
              "sec07-F04"
            ],
            "text": "Frame Rear Window Centered"
          }
        },
        {
          "estimated_narration_seconds": 47,
          "kind": "concept",
          "lines": [
            {
              "fact_ids": [
                "sec07-F05"
              ],
              "text": "Show only a sliver outside."
            },
            {
              "fact_ids": [
                "sec07-F05"
              ],
              "text": "Widen neighboring lane coverage."
            },
            {
              "fact_ids": [
                "sec07-F05"
              ],
              "text": "Set from normal seated position."
            }
          ],
          "media_absence_reason": "text_first_pilot",
          "media_role": "none",
          "narration": {
            "fact_ids": [
              "sec07-F05",
              "sec07-R04"
            ],
            "text": "Outside mirrors work best when they look outward, not inward. Set the outside mirrors so only a sliver of the vehicle side shows, widening coverage of neighboring lanes to shrink blind spots from a normal seated position. Keep your posture where you will actually drive while adjusting. That sliver is your reference that the angle is wide enough. The result is earlier sight of vehicles approaching beside you and safer lane changes."
          },
          "slide_id": "sec07-u02-s03",
          "title": {
            "fact_ids": [
              "sec07-F05"
            ],
            "text": "Keep Only Mirror Sliver"
          }
        },
        {
          "estimated_narration_seconds": 45,
          "kind": "trap",
          "lines": [
            {
              "fact_ids": [
                "sec07-F04",
                "sec07-F05"
              ],
              "text": "Inside centers, outside widens outward."
            },
            {
              "fact_ids": [
                "sec07-F04",
                "sec07-F05"
              ],
              "text": "Different mirrors, different aiming jobs."
            }
          ],
          "media_absence_reason": "text_first_pilot",
          "media_role": "none",
          "narration": {
            "fact_ids": [
              "sec07-F04",
              "sec07-F05"
            ],
            "text": "Drivers often swap these two mirror jobs, so hold the distinction. The inside mirror centers on the rear window with the matching day or night setting, while the outside mirrors show only a sliver of the vehicle side to widen neighboring lanes. One gives a stable rear view, the other shrinks blind spots. If your outside mirrors show much car side, they duplicate the inside view. Push them outward until the sliver appears."
          },
          "slide_id": "sec07-u02-s04",
          "title": {
            "fact_ids": [
              "sec07-F04",
              "sec07-F05"
            ],
            "text": "Separate Inside Outside Jobs"
          }
        },
        {
          "estimated_narration_seconds": 44,
          "kind": "self_check",
          "lines": [
            {
              "fact_ids": [
                "sec07-F05"
              ],
              "text": "How much side shows outside?"
            },
            {
              "fact_ids": [
                "sec07-F05"
              ],
              "text": "Picture normal seated mirror check."
            }
          ],
          "media_absence_reason": "text_first_pilot",
          "media_role": "none",
          "narration": {
            "fact_ids": [
              "sec07-F05"
            ],
            "text": "Here is a quick check: from your normal seated position, how much vehicle side belongs in the outside mirrors. Only a sliver of the vehicle side shows, which widens coverage of neighboring lanes. That image is your curb-side test before every drive. If you see a large panel of your own car, the mirrors are aimed too far inward. Adjust outward, hold posture steady, and confirm the wider lane view."
          },
          "slide_id": "sec07-u02-s05",
          "title": {
            "fact_ids": [
              "sec07-F05"
            ],
            "text": "Check Mirror Width Now"
          }
        },
        {
          "estimated_narration_seconds": 42,
          "kind": "close",
          "lines": [
            {
              "fact_ids": [
                "sec07-F04"
              ],
              "text": "Inside centered, glare controlled nightly."
            },
            {
              "fact_ids": [
                "sec07-R04"
              ],
              "text": "Outside sliver from seated position."
            }
          ],
          "media_absence_reason": "text_first_pilot",
          "media_role": "none",
          "narration": {
            "fact_ids": [
              "sec07-F04",
              "sec07-R04"
            ],
            "text": "Your mirror routine is now simple and repeatable. Frame the rear window with the inside mirror, match the day or night setting, then set outside mirrors to barely show each side from a normal seated position. Do this after the seat is fixed, because posture changes the view. Consistent mirrors mean earlier hazard sight and calmer lane changes. Make this two-step check part of every departure without exception."
          },
          "slide_id": "sec07-u02-s06",
          "title": {
            "fact_ids": [
              "sec07-F04"
            ],
            "text": "Repeat Mirror Routine Always"
          }
        }
      ],
      "title": {
        "fact_ids": [
          "sec07-F04"
        ],
        "text": "Aim Mirrors, Shrink Blind Spots"
      },
      "unit_id": "sec07-u02",
      "why_how": [
        {
          "fact_ids": [
            "sec07-F04"
          ],
          "text": "Centering on the rear window with the matching day or night setting gives a stable glare-controlled rear view."
        },
        {
          "fact_ids": [
            "sec07-F05"
          ],
          "text": "A sliver setting from a normal seated position widens neighboring-lane coverage and shrinks blind spots."
        }
      ],
      "worked_example": {
        "reasoning": {
          "fact_ids": [
            "sec07-F05"
          ],
          "text": "Moving the outside mirrors outward until only a sliver remains shifts the view toward adjacent lanes."
        },
        "result": {
          "fact_ids": [
            "sec07-F05"
          ],
          "text": "The driver spots a neighboring car sooner and delays the lane change safely."
        },
        "scenario": {
          "fact_ids": [
            "sec07-F04"
          ],
          "text": "A driver has the inside mirror centered but the outside mirrors show half the car side."
        }
      }
    },
    {
      "memory_support": {
        "fact_ids": [
          "sec07-F07",
          "sec07-R05"
        ],
        "text": "Hips hold lap, chest holds shoulder, never behind back."
      },
      "misconception": {
        "claim": {
          "fact_ids": [
            "sec07-F06"
          ],
          "text": "Trap: many people think belts are optional on short slow trips, which is wrong."
        },
        "correction": {
          "fact_ids": [
            "sec07-F06",
            "sec07-F09"
          ],
          "text": "Every person uses a fastened belt or child seat, because crash force equals weight times speed and bracing cannot resist it."
        }
      },
      "module_id": "sec07-m03",
      "objective_ids": [
        "sec07-F06",
        "sec07-F07",
        "sec07-F08"
      ],
      "self_check": {
        "answer": {
          "fact_ids": [
            "sec07-F07"
          ],
          "text": "Snug shoulder strap across shoulder and chest with lap low across hips, never under arm."
        },
        "prompt": {
          "fact_ids": [
            "sec07-F07"
          ],
          "text": "After buckling, how do you confirm your belt fit is correct?"
        },
        "rationale": {
          "fact_ids": [
            "sec07-F07"
          ],
          "text": "That placement spreads force across strong bones and keeps upper-body restraint working."
        }
      },
      "slides": [
        {
          "estimated_narration_seconds": 45,
          "kind": "opening",
          "lines": [
            {
              "fact_ids": [
                "sec07-F06"
              ],
              "text": "Everyone buckles every single trip."
            },
            {
              "fact_ids": [
                "sec07-F06"
              ],
              "text": "Belts keep you inside, in control."
            }
          ],
          "media_absence_reason": "text_first_pilot",
          "media_role": "none",
          "narration": {
            "fact_ids": [
              "sec07-F06"
            ],
            "text": "Belts are the simplest life-saving choice in your vehicle. Every person uses a fastened belt or child seat, because belts hold occupants inside, reduce crash injury, and help the driver keep control. There is no short-trip exception and no back-seat exception. This session connects the rule, the fit, the physics, and the enforcement behind it. Understand all four, and buckling becomes an automatic habit you never debate or delay."
          },
          "slide_id": "sec07-u03-s01",
          "title": {
            "fact_ids": [
              "sec07-F06"
            ],
            "text": "Buckle Everyone Every Trip"
          }
        },
        {
          "estimated_narration_seconds": 48,
          "kind": "concept",
          "lines": [
            {
              "fact_ids": [
                "sec07-F06"
              ],
              "text": "Every occupant restrained, always fastened."
            },
            {
              "fact_ids": [
                "sec07-F08"
              ],
              "text": "Utah law requires all passengers buckled."
            },
            {
              "fact_ids": [
                "sec07-F08"
              ],
              "text": "Young children need proper secured seats."
            }
          ],
          "media_absence_reason": "text_first_pilot",
          "media_role": "none",
          "narration": {
            "fact_ids": [
              "sec07-F06",
              "sec07-F08"
            ],
            "text": "The rule is universal and legally backed. Utah law requires every passenger to buckle up, and every child age eight or younger must ride properly secured in a car or booster seat. Beyond law, belts keep you from being thrown, reduce injury severity, and help the driver maintain control during sudden moves. As driver, you confirm every rider before moving. No one talks you out of this duty, regardless of distance, speed, or seating position."
          },
          "slide_id": "sec07-u03-s02",
          "title": {
            "fact_ids": [
              "sec07-F06"
            ],
            "text": "Universal Rule, Legal Duty"
          }
        },
        {
