          "media_absence_reason": "text_first_pilot",
          "media_role": "none",
          "narration": {
            "fact_ids": [
              "sec07-F10"
            ],
            "text": "Enforcement turns this duty into direct driver responsibility. A driver who carries an unrestrained passenger can receive one citation for each unrestrained person, with special stop authority when anyone under sixteen is unrestrained. That means three unrestrained riders can mean three citations. The law links your pre-drive check to real penalties. Confirm every belt, secure every child, and only then start the vehicle for the road ahead."
          },
          "slide_id": "sec07-u03-s05",
          "title": {
            "fact_ids": [
              "sec07-F10"
            ],
            "text": "Citations Multiply Per Rider"
          }
        },
        {
          "estimated_narration_seconds": 44,
          "kind": "self_check",
          "lines": [
            {
              "fact_ids": [
                "sec07-F07"
              ],
              "text": "Where should shoulder and lap sit?"
            },
            {
              "fact_ids": [
                "sec07-F07"
              ],
              "text": "Name the never-allowed routings too."
            }
