          "media_absence_reason": "text_first_pilot",
          "media_role": "none",
          "narration": {
            "fact_ids": [
              "sec07-F06",
              "sec07-R05"
            ],
            "text": "Close with a habit you can keep. Route the lap belt across the hips and the shoulder strap across the shoulder and chest, never under the arm or behind the back, for every person aboard. That single check honors the law, respects physics, and avoids per-person citations. Make belt confirmation your final pre-drive step. When everyone is buckled correctly, you drive calmer, safer, and fully in control of the vehicle."
          },
          "slide_id": "sec07-u03-s07",
          "title": {
            "fact_ids": [
              "sec07-F06"
            ],
            "text": "Make Buckling Automatic Habit"
          }
        }
