          "kind": "concept",
          "lines": [
            {
              "fact_ids": [
                "sec07-F12"
              ],
              "text": "Rear-facing in back to two."
            },
            {
              "fact_ids": [
                "sec07-F12"
              ],
              "text": "Forward harness in back to four."
            },
            {
              "fact_ids": [
                "sec07-F12"
              ],
              "text": "Booster until belt fits tall."
